cases.command:
FIND(COUNT(?a), COUNT(DISTINCT ?e)) WHERE {
  ?a ASSERTION {}
  STRUCTURAL (?a, "evidence", ?e)
  ?e EVIDENCE {evidence_class: "user_statement"}
}

